import type { None, Some } from "fp-ts/Option";
import type { ValidatorNEA, ValueFromValidator } from "./Types";
declare type IsOption<T> = T extends Some<unknown> ? true : T extends None ? true : false;
export declare type RequiredKeys<T> = {
    [K in keyof T]-?: IsOption<ValueFromValidator<T[K]>> extends true ? never : K;
}[keyof T];
export declare type OptionalKeys<T> = {
    [K in keyof T]-?: IsOption<ValueFromValidator<T[K]>> extends true ? K : never;
}[keyof T];
declare type ValueFromMaybeOption<T> = T extends Some<infer U> ? U : T extends None ? undefined : T;
export declare type UnwrappedValueFromValidator<V> = V extends ValidatorNEA<unknown, any, infer U> ? ValueFromMaybeOption<U> : never;
export {};
